<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { ArrowRight, BookOpen, CheckCircle2, ChevronDown, ChevronRight, FlaskConical, LockKeyhole } from 'lucide-vue-next'
import { RouterLink, useRoute, useRouter } from 'vue-router'
import AsyncState from '@/components/shared/AsyncState.vue'
import PageHeader from '@/components/shared/PageHeader.vue'
import { useRoadmapStore } from '@/stores/roadmap'
import type { RoadmapNode } from '@/types/product'

const route = useRoute(); const router = useRouter(); const roadmap = useRoadmapStore(); const selectedId = ref(String(route.params.nodeId ?? '')); const openIds = ref<string[]>([])
const current = computed(() => roadmap.current); const roots = computed(() => current.value?.roots ?? []); const selected = computed(() => { const all = [...roots.value, ...Object.values(roadmap.children).flat()]; return all.find((node) => node.id === selectedId.value) ?? roots.value[0] ?? null })
onMounted(async () => { await roadmap.loadCurrent(); const root = roots.value[0]; if (root) { await roadmap.loadChildren(root.roadmapId, root.id); openIds.value.push(root.id); if (!selectedId.value) selectedId.value = root.id } })
watch(() => route.params.nodeId, (id) => { if (typeof id === 'string' && id) selectedId.value = id })
async function toggle(node: RoadmapNode) { selectedId.value = node.id; if (current.value?.roadmap) await router.push({ name: 'roadmap-node', params: { roadmapId: current.value.roadmap.id, nodeId: node.id } }); if (node.childCount && current.value?.roadmap) { if (openIds.value.includes(node.id)) openIds.value = openIds.value.filter((id) => id !== node.id); else { await roadmap.loadChildren(current.value.roadmap.id, node.id); openIds.value.push(node.id) } } }
function statusLabel(node: RoadmapNode) { if (node.status === 'verified') return '已验证'; if (node.status === 'completed') return '已完成'; if (node.status === 'self_reported') return '自报掌握'; if (node.status === 'in_progress') return '学习中'; if (node.status === 'available') return '可开始'; return '后续开放' }
function statusIcon(node: RoadmapNode) { return node.status === 'locked' ? LockKeyhole : node.learningMode === 'lab' ? FlaskConical : node.status === 'completed' || node.status === 'verified' ? CheckCircle2 : BookOpen }
async function complete() { if (selected.value && current.value?.roadmap && selected.value.learningMode !== 'lab') await roadmap.complete(current.value.roadmap.id, selected.value) }
</script>

<template>
  <div class="page roadmap-page"><AsyncState :loading="roadmap.loading" :error="roadmap.error"><template #default><PageHeader eyebrow="02 · Roadmap" title="一张会随着实践点亮的能力树。" description="路线图保留长期方向，当前计划只取其中一段。点击一个分支，按需展开它的下一层。" :meta="[current?.roadmap?.goal ?? '尚未建立路线', `${current?.roadmap?.progress.completed ?? 0} / ${current?.roadmap?.progress.total ?? 0} 已完成`, '按需展开']" />
    <section v-if="current?.roadmap" class="roadmap-layout"><nav class="tree-panel" aria-label="能力路线树"><div class="tree-heading"><span>能力域</span><small>点击展开分支</small></div><div v-for="root in roots" :key="root.id" class="tree-group"><button class="tree-node root-node" :class="{ selected: selected?.id === root.id }" type="button" @click="toggle(root)"><component :is="openIds.includes(root.id) ? ChevronDown : ChevronRight" :size="14" aria-hidden="true" /><span><strong>{{ root.title }}</strong><small>{{ statusLabel(root) }} · {{ root.childCount }} 个分支</small></span><component :is="statusIcon(root)" :size="14" aria-hidden="true" /></button><div v-if="openIds.includes(root.id)" class="tree-children"><template v-for="capability in roadmap.children[root.id] ?? []" :key="capability.id"><button class="tree-node capability-node" :class="{ selected: selected?.id === capability.id }" type="button" @click="toggle(capability)"><component :is="openIds.includes(capability.id) ? ChevronDown : ChevronRight" :size="13" aria-hidden="true" /><span><strong>{{ capability.title }}</strong><small>{{ statusLabel(capability) }} · {{ capability.childCount }} 个节点</small></span><component :is="statusIcon(capability)" :size="13" aria-hidden="true" /></button><div v-if="openIds.includes(capability.id)" class="tree-leaves"><button v-for="leaf in roadmap.children[capability.id] ?? []" :key="leaf.id" class="tree-node leaf-node" :class="{ selected: selected?.id === leaf.id }" type="button" @click="toggle(leaf)"><component :is="statusIcon(leaf)" :size="12" aria-hidden="true" /><span><strong>{{ leaf.title }}</strong><small>{{ statusLabel(leaf) }}</small></span></button></div></template></div></div></nav>
      <article v-if="selected" class="node-panel"><div class="node-eyebrow"><component :is="statusIcon(selected)" :size="15" aria-hidden="true" /><span>{{ selected.nodeType === 'domain' ? '能力域' : selected.nodeType === 'capability' ? '能力分支' : '学习节点' }} · {{ statusLabel(selected) }}</span></div><h2>{{ selected.title }}</h2><p class="node-summary">{{ selected.summary }}</p><div class="node-facts"><div><small>完成标准</small><p>{{ selected.completionStandard }}</p></div><div><small>预计投入</small><p>{{ selected.estimatedMinutes }} 分钟</p></div></div><div v-if="selected.knowledgeCard.keyPoints?.length" class="knowledge-card"><small>知识卡</small><ul><li v-for="point in selected.knowledgeCard.keyPoints" :key="point">{{ point }}</li></ul></div><div class="node-action"><RouterLink v-if="selected.learningMode === 'lab' && current.currentPlan?.units.find((unit) => unit.roadmapNodeId === selected.id || unit.caseId === selected.caseId)" :to="{ name: 'lesson', query: { planUnitId: current.currentPlan.units.find((unit) => unit.roadmapNodeId === selected.id || unit.caseId === selected.caseId)?.id } }"><FlaskConical :size="14" aria-hidden="true" />进入真实实践 <ArrowRight :size="13" aria-hidden="true" /></RouterLink><button v-else-if="['concept', 'project'].includes(selected.nodeType) && selected.learningMode !== 'lab' && selected.status === 'available'" class="primary-button" type="button" @click="complete"><CheckCircle2 :size="14" aria-hidden="true" />确认我已完成</button><span v-else class="node-hint">{{ selected.status === 'locked' ? '完成前置节点后开放' : selected.status === 'self_reported' ? '这是用户自报掌握，不等同于验证' : selected.status === 'completed' ? '节点已完成，可以继续展开下一分支' : selected.nodeType === 'domain' || selected.nodeType === 'capability' ? '展开分支查看具体学习节点' : '关联实践完成后会自动验证' }}</span></div></article></section><section v-else class="empty-roadmap"><h2>还没有路线图</h2><p>先完成规划对话，路线图会在这里展开。</p><RouterLink to="/start">开始规划 <ArrowRight :size="14" aria-hidden="true" /></RouterLink></section>
  </template></AsyncState></div>
</template>

<style scoped>
.roadmap-page { max-width: 1120px; }.roadmap-layout { display: grid; grid-template-columns: minmax(300px, .9fr) minmax(0, 1.3fr); gap: 30px; margin-top: 29px; }.tree-panel { min-width: 0; border-top: 2px solid var(--blue); }.tree-heading { display: flex; justify-content: space-between; padding: 11px 0; color: var(--blue); font: 9px var(--mono); text-transform: uppercase; }.tree-heading small { color: var(--muted); text-transform: none; }.tree-group { border-bottom: 1px solid var(--line); }.tree-node { display: flex; align-items: center; width: 100%; gap: 8px; padding: 12px 8px; border: 0; background: transparent; color: #65716a; text-align: left; cursor: pointer; }.tree-node:hover, .tree-node.selected { background: var(--orange-soft); color: #9a5637; }.tree-node > span { min-width: 0; flex: 1; }.tree-node strong, .tree-node small { display: block; }.tree-node strong { overflow: hidden; color: inherit; font-size: 11px; font-weight: 500; text-overflow: ellipsis; white-space: nowrap; }.tree-node small { margin-top: 3px; color: #929a94; font: 8px var(--mono); }.root-node { padding-block: 14px; }.root-node strong { font: 400 17px var(--serif); }.tree-children { padding-left: 19px; border-left: 1px solid var(--line); }.capability-node { padding-block: 10px; }.tree-leaves { padding-left: 18px; border-left: 1px solid #e5dfd3; }.leaf-node { padding-block: 9px; }.leaf-node strong { font-size: 10px; }.node-panel { align-self: start; min-width: 0; padding: 18px 0 24px; border-top: 2px solid var(--orange); }.node-eyebrow { display: flex; align-items: center; gap: 7px; color: var(--blue); font: 9px var(--mono); text-transform: uppercase; }.node-panel h2 { margin: 14px 0 0; color: var(--ink); font: 400 30px/1.2 var(--serif); }.node-summary { max-width: 700px; margin: 12px 0 0; color: #66716b; font-size: 13px; line-height: 1.7; }.node-facts { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; margin-top: 25px; padding: 14px 0; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }.node-facts small, .knowledge-card > small { color: #818a84; font: 9px var(--mono); }.node-facts p { margin: 7px 0 0; color: #56635b; font-size: 11px; line-height: 1.55; }.knowledge-card { margin-top: 22px; }.knowledge-card ul { display: flex; flex-wrap: wrap; gap: 7px 18px; margin: 11px 0 0; padding-left: 17px; color: #56635b; font-size: 11px; line-height: 1.6; }.node-action { display: flex; align-items: center; gap: 14px; margin-top: 28px; }.node-action a, .primary-button { display: inline-flex; align-items: center; gap: 6px; min-height: 34px; padding: 8px 11px; border: 1px solid #b66844; background: var(--orange-soft); color: #995436; font-size: 10px; text-decoration: none; cursor: pointer; }.node-hint { color: #838c85; font: 10px/1.6 var(--mono); }.empty-roadmap { margin-top: 28px; padding: 20px 0; border-top: 2px solid var(--orange); }.empty-roadmap h2 { margin: 0; color: var(--ink); font: 400 22px var(--serif); }.empty-roadmap p { color: var(--muted); font-size: 11px; }.empty-roadmap a { display: inline-flex; align-items: center; gap: 6px; color: var(--blue); font-size: 10px; text-decoration: none; }
@media (max-width: 800px) { .roadmap-layout { grid-template-columns: 1fr; gap: 22px; }.node-panel { order: -1; }.node-panel h2 { font-size: 26px; } }
</style>
